head.script:
tailwind.config = {
  darkMode: "class",
  theme: {
    extend: {
      colors: {
        "primary": "#141414",
        "background-light": "#f7f7f7",
        "background-dark": "#191919",
      },
      fontFamily: {
        "display": ["Plus Jakarta Sans", "sans-serif"]
      },
      borderRadius: {"DEFAULT": "0.25rem", "lg": "0.5rem", "xl": "0.75rem", "full": "9999px"},
    },
  },
}

body.script:
function updateClock() {
    const now = new Date();
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    document.getElementById('currentTime').textContent = hours + ':' + minutes;
}
updateClock();
setInterval(updateClock, 1000);

document.querySelectorAll('.btn-start').forEach(btn => {
    btn.addEventListener('click', function() {
        const taskId = this.dataset.taskId;
        fetch('/my-tasks/start', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: {task_id: taskId}})
        })
        .then(r => r.json())
        .then(d => { if (d.result && d.result.success) location.reload(); else alert('Lỗi'); });
    });
});

document.querySelectorAll('.btn-complete').forEach(btn => {
    btn.addEventListener('click', function() {
        const taskId = this.dataset.taskId;
        if (!confirm('Xác nhận hoàn thành?')) return;
        fetch('/my-tasks/complete', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: {task_id: taskId}})
        })
        .then(r => r.json())
        .then(d => { if (d.result && d.result.success) location.reload(); else alert('Lỗi'); });
    });
});

setInterval(() => location.reload(), 30000);
